export interface Position {
  line: number;
  col: number;
}

export class TemplateError extends Error {
  line: number;
  column: number;
  constructor(message: string, pos: Position) {
    super(`${message} (line ${pos.line}, column ${pos.col})`);
    this.name = "TemplateError";
    this.line = pos.line;
    this.column = pos.col;
  }
}

type Token =
  | { type: "text"; value: string; pos: Position }
  | { type: "interp"; path: string; escaped: boolean; pos: Position }
  | { type: "if"; path: string; pos: Position }
  | { type: "each"; path: string; pos: Position }
  | { type: "else"; pos: Position }
  | { type: "close"; name: "if" | "each"; pos: Position }
  | { type: "comment"; pos: Position };

type Node =
  | { type: "text"; value: string }
  | { type: "interp"; path: string; escaped: boolean; pos: Position }
  | { type: "if"; path: string; thenBody: Node[]; elseBody: Node[] | null; pos: Position }
  | { type: "each"; path: string; body: Node[]; elseBody: Node[] | null; pos: Position }
  | { type: "comment" };

function lineCol(src: string, offset: number): Position {
  let line = 1;
  let col = 1;
  for (let i = 0; i < offset && i < src.length; i++) {
    if (src[i] === "\n") {
      line++;
      col = 1;
    } else {
      col++;
    }
  }
  return { line, col };
}

function tokenize(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  const n = src.length;
  while (i < n) {
    if (src[i] === "{" && src[i + 1] === "{") {
      const isTriple = src[i + 2] === "{";
      const openLen = isTriple ? 3 : 2;
      const closeStr = isTriple ? "}}}" : "}}";
      const closeIdx = src.indexOf(closeStr, i + openLen);
      if (closeIdx === -1) {
        throw new TemplateError("Unclosed tag", lineCol(src, i));
      }
      const inner = src.slice(i + openLen, closeIdx);
      const pos = lineCol(src, i);
      if (isTriple) {
        const path = inner.trim();
        if (!path) {
          throw new TemplateError("Empty expression", pos);
        }
        tokens.push({ type: "interp", path, escaped: false, pos });
      } else {
        tokens.push(parseTagInner(inner, pos));
      }
      i = closeIdx + closeStr.length;
    } else {
      let next = src.indexOf("{{", i);
      if (next === -1) {
        next = n;
      }
      tokens.push({ type: "text", value: src.slice(i, next), pos: lineCol(src, i) });
      i = next;
    }
  }
  return tokens;
}

function parseTagInner(inner: string, pos: Position): Token {
  const trimmed = inner.trim();
  if (!trimmed) {
    throw new TemplateError("Empty expression", pos);
  }
  const first = trimmed[0];
  if (first === "#") {
    const rest = trimmed.slice(1).trim();
    const sp = rest.indexOf(" ");
    const keyword = sp === -1 ? rest : rest.slice(0, sp);
    const path = sp === -1 ? "" : rest.slice(sp + 1).trim();
    if (keyword === "if") {
      if (!path) {
        throw new TemplateError("#if requires a path", pos);
      }
      return { type: "if", path, pos };
    } else if (keyword === "each") {
      if (!path) {
        throw new TemplateError("#each requires a path", pos);
      }
      return { type: "each", path, pos };
    } else {
      throw new TemplateError(`Unknown block tag #${keyword}`, pos);
    }
  }
  if (first === "/") {
    const name = trimmed.slice(1).trim();
    if (name === "if") {
      return { type: "close", name: "if", pos };
    }
    if (name === "each") {
      return { type: "close", name: "each", pos };
    }
    throw new TemplateError(`Unknown closing tag /${name}`, pos);
  }
  if (trimmed === "else") {
    return { type: "else", pos };
  }
  if (first === "!") {
    return { type: "comment", pos };
  }
  return { type: "interp", path: trimmed, escaped: true, pos };
}

class Parser {
  private tokens: Token[];
  private i: number;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
    this.i = 0;
  }

  parse(): Node[] {
    return this.parseNodes(null);
  }

  private peek(): Token | undefined {
    return this.tokens[this.i];
  }

  private parseNodes(closingFor: "if" | "each" | null): Node[] {
    const nodes: Node[] = [];
    while (this.i < this.tokens.length) {
      const token = this.tokens[this.i];
      switch (token.type) {
        case "text": {
          nodes.push({ type: "text", value: token.value });
          this.i++;
          break;
        }
        case "comment": {
          nodes.push({ type: "comment" });
          this.i++;
          break;
        }
        case "interp": {
          nodes.push({
            type: "interp",
            path: token.path,
            escaped: token.escaped,
            pos: token.pos,
          });
          this.i++;
          break;
        }
        case "if": {
          this.i++;
          const thenBody = this.parseNodes("if");
          let elseBody: Node[] | null = null;
          if (this.peek()?.type === "else") {
            this.i++;
            elseBody = this.parseNodes("if");
            if (this.peek()?.type === "else") {
              throw new TemplateError(
                "Duplicate {{else}} in #if block",
                this.peek()!.pos,
              );
            }
          }
          this.expectClose("if", token.pos);
          nodes.push({
            type: "if",
            path: token.path,
            thenBody,
            elseBody,
            pos: token.pos,
          });
          break;
        }
        case "each": {
          this.i++;
          const body = this.parseNodes("each");
          let elseBody: Node[] | null = null;
          if (this.peek()?.type === "else") {
            this.i++;
            elseBody = this.parseNodes("each");
            if (this.peek()?.type === "else") {
              throw new TemplateError(
                "Duplicate {{else}} in #each block",
                this.peek()!.pos,
              );
            }
          }
          this.expectClose("each", token.pos);
          nodes.push({
            type: "each",
            path: token.path,
            body,
            elseBody,
            pos: token.pos,
          });
          break;
        }
        case "else": {
          if (closingFor !== null) {
            return nodes;
          }
          throw new TemplateError("{{else}} outside of a block", token.pos);
        }
        case "close": {
          if (closingFor === null) {
            throw new TemplateError(
              `Unexpected {{/${token.name}}} without a matching opening`,
              token.pos,
            );
          }
          if (token.name !== closingFor) {
            throw new TemplateError(
              `Mismatched closing tag: expected {{/${closingFor}}} but found {{/${token.name}}}`,
              token.pos,
            );
          }
          return nodes;
        }
      }
    }
    return nodes;
  }

  private expectClose(name: string, openPos: Position): void {
    const token = this.peek();
    if (!token) {
      throw new TemplateError(`Unclosed #${name} block`, openPos);
    }
    if (token.type !== "close") {
      throw new TemplateError(
        `Expected {{/${name}}} but found something else`,
        token.pos,
      );
    }
    if (token.name !== name) {
      throw new TemplateError(
        `Mismatched closing tag: expected {{/${name}}} but found {{/${token.name}}}`,
        token.pos,
      );
    }
    this.i++;
  }
}

interface Scope {
  root: unknown;
  thisVal: unknown;
  index: number | null;
}

function resolvePath(path: string, scope: Scope): unknown {
  const trimmed = path.trim();
  if (trimmed === "this") {
    return scope.thisVal;
  }
  if (trimmed === "@index") {
    return scope.index;
  }
  if (trimmed.startsWith("this.")) {
    return lookup(scope.thisVal, trimmed.slice(5));
  }
  return lookup(scope.root, trimmed);
}

function lookup(obj: unknown, path: string): unknown {
  if (path === "") {
    return obj;
  }
  const parts = path.split(".");
  let cur: unknown = obj;
  for (const part of parts) {
    if (cur == null) {
      return undefined;
    }
    if (typeof cur !== "object") {
      return undefined;
    }
    cur = (cur as Record<string, unknown>)[part];
  }
  return cur;
}

function isTruthy(val: unknown): boolean {
  if (val === null || val === undefined) {
    return false;
  }
  if (val === false) {
    return false;
  }
  if (val === 0) {
    return false;
  }
  if (val === "") {
    return false;
  }
  if (Array.isArray(val) && val.length === 0) {
    return false;
  }
  return true;
}

function escapeHtml(s: string): string {
  let out = "";
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    switch (c) {
      case "&":
        out += "&amp;";
        break;
      case "<":
        out += "&lt;";
        break;
      case ">":
        out += "&gt;";
        break;
      case '"':
        out += "&quot;";
        break;
      case "'":
        out += "&#39;";
        break;
      default:
        out += c;
    }
  }
  return out;
}

function renderValue(val: unknown, escaped: boolean, pos: Position): string {
  if (val === null || val === undefined) {
    return "";
  }
  const t = typeof val;
  if (t === "string") {
    return escaped ? escapeHtml(val) : val;
  }
  if (t === "number" || t === "boolean" || t === "bigint") {
    return String(val);
  }
  const typeDesc = Array.isArray(val) ? "array" : t;
  throw new TemplateError(`Cannot render ${typeDesc} value as text`, pos);
}

function renderNodes(nodes: Node[], scope: Scope): string {
  let out = "";
  for (const node of nodes) {
    out += renderNode(node, scope);
  }
  return out;
}

function renderNode(node: Node, scope: Scope): string {
  switch (node.type) {
    case "text":
      return node.value;
    case "comment":
      return "";
    case "interp": {
      const val = resolvePath(node.path, scope);
      return renderValue(val, node.escaped, node.pos);
    }
    case "if": {
      const cond = resolvePath(node.path, scope);
      if (isTruthy(cond)) {
        return renderNodes(node.thenBody, scope);
      } else if (node.elseBody !== null) {
        return renderNodes(node.elseBody, scope);
      }
      return "";
    }
    case "each": {
      const arr = resolvePath(node.path, scope);
      if (Array.isArray(arr)) {
        if (arr.length === 0) {
          return node.elseBody ? renderNodes(node.elseBody, scope) : "";
        }
        let out = "";
        for (let i = 0; i < arr.length; i++) {
          out += renderNodes(node.body, {
            root: scope.root,
            thisVal: arr[i],
            index: i,
          });
        }
        return out;
      }
      if (arr === null || arr === undefined) {
        return node.elseBody ? renderNodes(node.elseBody, scope) : "";
      }
      return "";
    }
  }
}

export function render(template: string, data: unknown): string {
  const tokens = tokenize(template);
  const parser = new Parser(tokens);
  const ast = parser.parse();
  const scope: Scope = { root: data, thisVal: data, index: null };
  return renderNodes(ast, scope);
}

