import { test, expect } from "bun:test";
import { render, TemplateError } from "../src/engine.ts";

test("basic interpolation", () => {
  expect(render("Hello {{name}}!", { name: "World" })).toBe("Hello World!");
});

test("nested path interpolation", () => {
  expect(
    render("{{user.name.first}}", { user: { name: { first: "Ada" } } }),
  ).toBe("Ada");
});

test("html escaping", () => {
  expect(
    render("{{value}}", { value: "<script>alert('x')</script>" }),
  ).toBe("&lt;script&gt;alert(&#39;x&#39;)&lt;/script&gt;");
});

test("ampersand escaping", () => {
  expect(render("{{value}}", { value: "Tom & Jerry" })).toBe("Tom &amp; Jerry");
});

test("double quote escaping", () => {
  expect(render("{{value}}", { value: 'say "hi"' })).toBe("say &quot;hi&quot;");
});

test("unescaped triple mustache", () => {
  expect(render("{{{value}}}", { value: "<b>bold</b>" })).toBe("<b>bold</b>");
});

test("missing value renders empty", () => {
  expect(render("Hello {{missing}}!", {})).toBe("Hello !");
});

test("null renders empty", () => {
  expect(render("[{{value}}]", { value: null })).toBe("[]");
});

test("undefined renders empty", () => {
  expect(render("[{{value}}]", { value: undefined })).toBe("[]");
});

test("number and boolean rendering", () => {
  expect(render("{{n}} {{b}}", { n: 42, b: true })).toBe("42 true");
});

test("zero renders as 0", () => {
  expect(render("{{n}}", { n: 0 })).toBe("0");
});

test("if true", () => {
  expect(render("{{#if show}}yes{{/if}}", { show: true })).toBe("yes");
});

test("if false", () => {
  expect(render("{{#if show}}yes{{/if}}", { show: false })).toBe("");
});

test("if else - false branch", () => {
  expect(
    render("{{#if show}}yes{{else}}no{{/if}}", { show: false }),
  ).toBe("no");
});

test("if else - true branch", () => {
  expect(
    render("{{#if show}}yes{{else}}no{{/if}}", { show: true }),
  ).toBe("yes");
});

test("nested if", () => {
  const tpl =
    "{{#if a}}{{#if b}}both{{else}}only-a{{/if}}{{else}}no-a{{/if}}";
  expect(render(tpl, { a: true, b: true })).toBe("both");
  expect(render(tpl, { a: true, b: false })).toBe("only-a");
  expect(render(tpl, { a: false, b: true })).toBe("no-a");
});

test("truthiness rules", () => {
  const f = (v: unknown) =>
    render("{{#if v}}T{{else}}F{{/if}}", { v });
  expect(f("")).toBe("F");
  expect(f(0)).toBe("F");
  expect(f(false)).toBe("F");
  expect(f(null)).toBe("F");
  expect(f(undefined)).toBe("F");
  expect(f([])).toBe("F");
  expect(f("x")).toBe("T");
  expect(f(1)).toBe("T");
  expect(f([1])).toBe("T");
  expect(f({})).toBe("T");
  expect(f("0")).toBe("T");
});

test("each basic", () => {
  expect(
    render("{{#each items}}{{this}},{{/each}}", { items: ["a", "b", "c"] }),
  ).toBe("a,b,c,");
});

test("each with @index", () => {
  expect(
    render("{{#each items}}{{@index}}:{{this}} {{/each}}", {
      items: ["a", "b"],
    }),
  ).toBe("0:a 1:b ");
});

test("each else for empty array", () => {
  expect(
    render("{{#each items}}{{this}}{{else}}empty{{/each}}", { items: [] }),
  ).toBe("empty");
});

test("each else for missing", () => {
  expect(
    render("{{#each items}}{{this}}{{else}}missing{{/each}}", {}),
  ).toBe("missing");
});

test("each with this properties", () => {
  expect(
    render("{{#each users}}{{this.name}} {{/each}}", {
      users: [{ name: "A" }, { name: "B" }],
    }),
  ).toBe("A B ");
});

test("nested each via this", () => {
  const tpl =
    "{{#each outer}}{{#each this.inner}}{{this}},{{/each}};{{/each}}";
  const data = { outer: [{ inner: [1, 2] }, { inner: [3] }] };
  expect(render(tpl, data)).toBe("1,2;3,;");
});

test("each falls back to root for normal paths", () => {
  const tpl = "{{#each items}}{{globalValue}}{{/each}}";
  expect(render(tpl, { items: [1, 2], globalValue: "G" })).toBe("GG");
});

test("if inside each", () => {
  const tpl =
    "{{#each items}}{{#if this.active}}{{this.name}} {{/if}}{{/each}}";
  expect(
    render(tpl, {
      items: [
        { name: "A", active: true },
        { name: "B", active: false },
        { name: "C", active: true },
      ],
    }),
  ).toBe("A C ");
});

test("comment emits nothing", () => {
  expect(render("a{{! this is a comment }}b", {})).toBe("ab");
});

test("comment with no spaces", () => {
  expect(render("a{{!comment}}b", {})).toBe("ab");
});

test("whitespace preserved", () => {
  expect(render("  {{name}}  \n  ", { name: "x" })).toBe("  x  \n  ");
});

test("whitespace inside tags is trimmed", () => {
  expect(render("{{  name  }}", { name: "x" })).toBe("x");
});

test("array index via dot path", () => {
  expect(render("{{items.0}}", { items: ["first", "second"] })).toBe("first");
});

test("errors: unclosed if", () => {
  expect(() => render("{{#if a}}text", { a: true })).toThrow(TemplateError);
});

test("errors: mismatched close", () => {
  expect(() => render("{{#if a}}{{/each}}", { a: true })).toThrow(
    TemplateError,
  );
});

test("errors: duplicate else", () => {
  expect(() =>
    render("{{#if a}}{{else}}{{else}}{{/if}}", { a: true }),
  ).toThrow(TemplateError);
});

test("errors: else outside block", () => {
  expect(() => render("{{else}}", {})).toThrow(TemplateError);
});

test("errors: close without open", () => {
  expect(() => render("{{/if}}", {})).toThrow(TemplateError);
});

test("errors: unknown block", () => {
  expect(() => render("{{#for x}}{{/for}}", {})).toThrow(TemplateError);
});

test("errors: unknown close", () => {
  expect(() => render("{{#if a}}{{/for}}{{/if}}", { a: true })).toThrow(
    TemplateError,
  );
});

test("errors: object interpolation", () => {
  expect(() => render("{{obj}}", { obj: { a: 1 } })).toThrow(TemplateError);
});

test("errors: array interpolation", () => {
  expect(() => render("{{arr}}", { arr: [1, 2] })).toThrow(TemplateError);
});

test("errors: function interpolation", () => {
  expect(() => render("{{fn}}", { fn: () => 1 })).toThrow(TemplateError);
});

test("errors: unclosed tag", () => {
  expect(() => render("{{unclosed", {})).toThrow(TemplateError);
});

test("errors: empty expression", () => {
  expect(() => render("{{}}", {})).toThrow(TemplateError);
});

test("error has line and column", () => {
  try {
    render("line1\n{{#if a}}\ntext", { a: true });
    expect.unreachable("should have thrown");
  } catch (e) {
    expect(e).toBeInstanceOf(TemplateError);
    expect((e as TemplateError).line).toBe(2);
    expect((e as TemplateError).column).toBe(1);
  }
});

test("error column for mismatched close", () => {
  try {
    render("{{#if a}}\n{{/each}}", { a: true });
    expect.unreachable("should have thrown");
  } catch (e) {
    expect(e).toBeInstanceOf(TemplateError);
    expect((e as TemplateError).line).toBe(2);
  }
});

