import { test, expect } from "bun:test";
import { spawnSync } from "node:child_process";
import { writeFileSync, mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const CLI = join(process.cwd(), "src", "cli.ts");

function runCli(templatePath: string, dataPath: string) {
  return spawnSync("bun", ["run", CLI, templatePath, dataPath], {
    encoding: "utf-8",
  });
}

test("cli renders template with data", () => {
  const dir = mkdtempSync(join(tmpdir(), "mini-template-"));
  const tplPath = join(dir, "tpl.txt");
  const dataPath = join(dir, "data.json");
